var dir="Docs/CR016-017";var forest=Newtonsoft.Json.JsonConvert.DeserializeObject<Vector3[]>(System.IO.File.ReadAllText(dir+"/forest-path.json"));for(int i=0;i<forest.Length;i++)forest[i].y=Racer.Editor.Phase6Buildings.Ground(forest[i]);
var from=Racer.Editor.CompactYard.House+new Vector3(15,0,8);Racer.Editor.StreetLoopBuilder.Nearest(from,Racer.Editor.StreetLoopBuilder.Route(),out var to);var access=Enumerable.Range(0,40).Select(i=>{var p=Vector3.Lerp(from,to,i/39f);p.y=Racer.Editor.Phase6Buildings.Ground(p);return p;}).ToArray();
var plan=new Racer.WoodlandBenchmark.Plan{seconds=42,routes=new[]{new Racer.WoodlandBenchmark.Route{name="reforested-old-yard",points=forest,speed=3.5f,lookAhead=3},new Racer.WoodlandBenchmark.Route{name="house-access-out",points=access,speed=4,lookAhead=4},new Racer.WoodlandBenchmark.Route{name="house-access-in",points=access.Reverse().ToArray(),speed=4,lookAhead=4}}};System.IO.File.WriteAllText(dir+"/local-drive-routes.json",JsonUtility.ToJson(plan,true));return "Routes grounded";
